"""Bay City Commoners: ordinary people for the core set, in the Chapter 7 adversary format.
Usage: python3 commoners.py SYSTEM_DIR  -> data/commoner-catalog.json"""
import json, sys
B = sys.argv[1]
def C(id, name, cat, attrs, dice, health, ego, speed, minion, noncombat, bonuses, gear, notes, look, ring):
    S, P, E, W, A, I = attrs; dS, dP, dE, dW, dA, dI = dice
    return dict(id=id, name=name, category=cat, source='Altered Carbon RPG system: Bay City commoners (built on the Core Ch.7 adversary format)',
                attributes=dict(strength=S, perception=P, empathy=E, willpower=W, acuity=A, intelligence=I),
                attributeSkillDice=dict(strength=dS, perception=dP, empathy=dE, willpower=dW, acuity=dA, intelligence=dI),
                skillBonuses=bonuses, health=health, ego=ego, speedDice=speed, defense=0, minionBonus=minion, nonCombatant=noncombat,
                equipment=gear, specialRules=[], triggeredEffects=[], armorNote='', gmNotes=notes, look=look, ring=ring)
